function validateListSessionsMessage(message: Record<string, unknown>): ValidationResult {
  if (
    message.limit !== undefined &&
    (!Number.isInteger(message.limit) || (message.limit as number) < 1 || (message.limit as number) > 200)
  ) {
    return {valid: false, error: 'limit must be an integer between 1 and 200'};
  }

  let before: {updatedAt: string; sessionId: string} | undefined;
  if (message.before === undefined) {
    return {
      valid: true,
      data: {
        type: 'list_sessions',
        limit: message.limit as number | undefined,
        before,
      },
    };
  }

  if (typeof message.before !== 'object' || message.before === null || Array.isArray(message.before)) {
    return {valid: false, error: 'before must be an object'};
  }

  const beforeObj = message.before as Record<string, unknown>;
  if (typeof beforeObj.updatedAt !== 'string' || isNaN(Date.parse(beforeObj.updatedAt))) {
    return {valid: false, error: 'before.updatedAt must be a valid ISO date string'};
  }

  if (typeof beforeObj.sessionId !== 'string' || beforeObj.sessionId.length < 1 || beforeObj.sessionId.length > 128) {
    return {valid: false, error: 'before.sessionId must be a string of 1-128 characters'};
  }

  before = {updatedAt: beforeObj.updatedAt, sessionId: beforeObj.sessionId};

  return {
    valid: true,
    data: {
      type: 'list_sessions',
      limit: message.limit as number | undefined,
      before,
    },
  };
}

